import json,statistics,datetime,html
from pathlib import Path
p=Path(__file__).resolve().parents[2] / 'reports/isports-comparison-2026-10-26';bf=json.load(open(p/'betfair-reference.json'));isp=json.load(open(p/'correct-score.json'));sites=json.load(open(p/'site-captures.json'));sched={e['matchId']:e for e in json.load(open(p/'schedule.json'))['response']['data']};mp={'228826039':'36225095','212117923':'36239988','222117924':'36239995'};rows=[];summary=[]
for s in sites:
 e=bf['events'][mp[s['matchId']]]; bm={r['runner'].replace(' ',''):r for r in e['markets']}; fixture=e['team1']+' v '+e['team2'];kick=datetime.datetime.fromtimestamp(sched[s['matchId']]['matchTime'],datetime.timezone.utc).isoformat();assert datetime.datetime.fromisoformat(kick)==datetime.datetime.fromisoformat(e['openTimestamp'].replace('Z','+00:00'))
 for company in [c for c in isp['response']['data'] if c['matchId']==s['matchId']]:
  iq={f"{r['homeScore']}-{r['awayScore']}":float(r['odds']) for r in company['odds']['bettingOddsItems']}; cr=[]
  for r in s['rows']:
   h=iq.get(r['score'],0);b=bm.get(r['score']);
   if h<=0 or not b or b.get('layOdds',0)<=1:continue
   out=dict(fixture=fixture,isportsMatchId=s['matchId'],betfairEventId=mp[s['matchId']],kickoff=kick,score=r['score'],companyId=company['companyId'],companyName={'3':'Crown','31':'Sbobet'}.get(company['companyId'],company['companyId']),isportsNetBackOdds=h,isportsDecimalBackOdds=h+1,betfairDecimalBackOdds=b.get('backOdds'),betfairDecimalLayOdds=b['layOdds'],betfairLaySize=b.get('laySize'),betfairGrossReturnPercent=100/(b['layOdds']-1),hypotheticalReturnAtIsportsPricePercent=100/h,siteReturnPercent=r['sitePercent'],siteToHypotheticalRatio=r['sitePercent']*h/100,siteCapturedAt=s['capturedAt'],isportsCapturedAt=isp['capturedAt'],isportsOddsLastChangedAt=datetime.datetime.fromtimestamp(company['changeTime'],datetime.timezone.utc).isoformat(),betfairCapturedAt=bf['capturedAt']);rows.append(out);cr.append(out)
  summary.append(dict(fixture=fixture,company=cr[0]['companyName'],pairs=len(cr),medianSiteToHypotheticalRatio=statistics.median(r['siteToHypotheticalRatio'] for r in cr)))
report=dict(scope='3 matched prematch fixtures; 48 unique numeric score selections, 64 bookmaker-score comparisons. Matched both teams and exact kickoff. Site figures captured freshly, no bets placed.',definitions={'isports':'Bookmaker BACK correct-score net odds. Decimal = net + 1. Not an exchange lay quote.','betfair':'Exchange decimal back and lay quotes as supplied by betfair-odds.com.','hypothetical':'100 / isportsNetBackOdds is profit per 100 liability ONLY IF one hypothetically offered lay at that same decimal back price. It is not an executable lay price supplied by iSports.','site':'Displayed percentage; stake/settlement basis remains unverified.'},limitations='Snapshots not simultaneous. iSports capture 09:00:15 UTC; website 09:01:52–09:03:27 UTC; Betfair reference 09:03 UTC. Individual changeTime is last price change, not necessarily feed delay. A quoted price is not a guaranteed executable amount. No claim of a universal site pricing formula.',summary=summary,rows=rows)
