body=''
for s in sites:
 rr=[r for r in rows if r['isportsMatchId']==s['matchId']];body+='<h2>'+html.escape(rr[0]['fixture'])+'</h2><img src="site-'+s['matchId']+'.jpg"><table><tr><th>Company</th><th>Score</th><th>iSports net back</th><th>iSports decimal back</th><th>BF back</th><th>BF lay</th><th>BF return %</th><th>Hypothetical iSports-price lay return %</th><th>Site %</th></tr>'
 for r in rr:body+='<tr>'+''.join('<td>'+html.escape(str(r[k]) if not isinstance(r[k],float) else f'{r[k]:.4f}')+'</td>' for k in ['companyName','score','isportsNetBackOdds','isportsDecimalBackOdds','betfairDecimalBackOdds','betfairDecimalLayOdds','betfairGrossReturnPercent','hypotheticalReturnAtIsportsPricePercent','siteReturnPercent'])+'</tr>'
 body+='</table>'
